current.custom_css:
.font-black {
  font-weight: 900;
}
body .m-quantity {
	border-radius: 0;
}
.m-custom-image-with-text .m-hero__content .m-hero__title {
  margin-bottom: 0px;
}

.m-custom-image-with-text .m-hero__content .m-hero__text {
  font-weight: 700;
}

.m-section__heading {
  text-transform: uppercase;
}

.m-footer--block-title {
  text-transform: uppercase;
}

.m-footer--bottom-inner {
  border-top: 1px solid #313131;
}

.m-custom-newsletters form .m-newsletter-form__input {
  background: #efefef;
  border: 0;
  width: unset !important;
  flex: 1 1 0%;
  height: 50px;
  border-radius: 0;
}

.m-custom-newsletters form button[type="submit"] {
  background: #000;
  color: #fff;
  border: 0;
  border-radius: 0;
}

.m-custom-newsletters form button[type="submit"]:hover {
  color: #fff;
}

.m-custom-newsletters .m-newsletter-form--bordered .m-newsletter-form__input {
  border: none;
  width: 650px;
  max-width: 100%;
}

.m-custom-newsletters .m-newsletter-form__button {
  padding: 0.5rem 1rem;
  font-weight: bold;
  font-size: 1rem;
  line-height: 1.6;
}

.m-header__desktop .m-header__menu .m-menu__item .m-menu__link--main {
  font-weight: 700;
}

.h5,
.h6,
.m-product-card__name {
  font-family: 'M-Body-Font';
  font-weight: 400;
  line-height: calc(var(--base-line-height) * 1px);
}

.m-price__regular {
  font-weight: 700;
}

@media (min-width: 1920px) {
  .m-custom-image-with-text .m-hero__title {
    font-size: 140px !important;
  }

  .m-custom-image-with-text .m-hero__text {
    font-size: 30px !important;
  }

  .m-custom-image-with-text .m-hero__content {
    max-width: 100%;
  }
}
